<template><div class="page-screen"><header class="page-head"><div><h1 class="page-title">系统管理</h1><p class="page-subtitle">服务状态、Form 目录同步、迁移映射与审计。</p></div><div class="head-actions"><button class="btn" @click="load"><Icon name="refresh"/>刷新</button><button v-if="allowed" class="btn primary" :disabled="busy" @click="run(syncNow)"><Icon name="refresh"/>立即同步</button></div></header><div class="segmented"><button v-for="t in [['status','服务状态'],['mapping','迁移映射'],['audit','审计日志']]" :key="t[0]" :class="{active:tab===t[0]}" @click="switchTab(t[0])">{{t[1]}}</button></div><div class="table-page-body"><div v-if="tab==='mapping'" class="toolbar"><select class="input" v-model="mappingKind" @change="loadMappings"><option v-for="k in kinds" :key="k[0]" :value="k[0]">{{k[1]}}</option></select><input class="input directory-search" type="search" v-model="keyword" placeholder="名称、工号或稳定ID"/><button class="btn small" @click="run(validate)">切换校验</button><button v-if="mappingKind==='units'" class="btn small" @click="run(api.exportFormUnitMappings)">导出组织 CSV</button><label v-if="mappingKind==='units'" class="btn small">导入组织 CSV<input type="file" accept=".csv,text/csv" hidden @change="importCsv"/></label></div><div v-if="tab==='audit'" class="toolbar audit-filters"><input class="input" v-model="auditPerson" placeholder="工号对应的人员 key"/><select class="input" v-model="auditAction"><option value="">全部行为</option><option v-for="a in actions" :key="a[0]" :value="a[0]">{{a[1]}}</option></select><input class="input" type="date" v-model="since"/><input class="input" type="date" v-model="until"/><button class="btn small" @click="page=1;loadAudit()">查询</button></div><div class="table-shell"><div class="table-scroll"><div v-if="error" class="empty"><h3>{{allowed?'加载失败':'无法访问'}}</h3><p>{{error}}</p><button class="btn" @click="load">重试</button></div><div v-else-if="busy" class="empty">正在加载…</div><template v-else-if="allowed"><div v-if="tab==='status'" class="spaces-content"><section class="status-metrics"><article v-for="m in metrics" :key="m.label" class="next-metric"><span>{{m.label}}</span><strong>{{m.value}}</strong></article></section><section class="next-admin-section"><h2>同步状态</h2><dl class="admin-facts"><div v-for="(v,k) in statusFields" :key="k"><dt>{{k}}</dt><dd>{{v??'—'}}</dd></div></dl><p v-if="syncState.lastFailureReason||syncState.failureLog" class="error-text">{{syncState.lastFailureReason||syncState.failureLog}}</p></section><section class="next-admin-section"><h2>配置与连通性</h2><dl class="admin-facts"><div v-for="(v,k) in config" :key="k"><dt>{{k}}</dt><dd>{{typeof v==='object'?JSON.stringify(v):v}}</dd></div></dl></section></div><template v-else-if="tab==='mapping'"><div class="info-strip"><Icon name="info"/><span>待处理阻断项 {{overview.blockerCount??validation?.blockers?.length??'—'}}；{{validation?.ready?'校验通过':'以最新切换校验结果为准'}}</span></div><table class="next-data-table"><thead><tr><th>对象</th><th>稳定 ID</th><th>canonical / 历史 OA</th><th>决策</th><th>影响引用</th><th>操作</th></tr></thead><tbody><tr v-for="row in mappingPage" :key="stableId(row)"><td>{{row.displayName||row.name||row.unitName||row.identityName||'—'}}<small>{{row.employeeNoSnapshot||row.employeeNo||''}}</small></td><td class="mono">{{stableId(row)}}</td><td class="mono">{{canonical(row)||'未绑定'}}<small>{{legacy(row)}}</small></td><td>{{row.migrationDecision||row.status||'PENDING'}}</td><td>{{row.affectedReferenceCount||0}}</td><td><button class="text-button" @click="run(()=>editMapping(row))">处理</button></td></tr></tbody></table><div v-if="!filteredMappings.length" class="empty">暂无匹配记录</div></template><template v-else><table class="next-data-table"><thead><tr><th>时间</th><th>人员</th><th>行为</th><th>目标</th><th>操作</th></tr></thead><tbody><tr v-for="row in logs" :key="row.id"><td>{{time(row.createdAt)}}</td><td>{{row.employeeNo||row.personKey||row.personOaId||'—'}}</td><td>{{actionName(row.action)}}</td><td>{{row.targetType}}<small class="mono">{{row.targetId}}</small></td><td><button class="text-button" @click="showLog(row)">详情</button></td></tr></tbody></table><div v-if="!logs.length" class="empty">暂无匹配审计</div></template></template></div><Pager v-if="tab!=='status'" :page="page" :total="tab==='mapping'?filteredMappings.length:auditTotal" :size="size" @page="setPage" @size="setSize"/></div></div></div></template>
<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import Icon from '../components/Icon.vue';import Pager from '../components/Pager.vue';import * as api from '../api';import {run,dialog,confirm,notify} from '../state';import {formatTime as time} from '../../utils/formatters';
const route=useRoute(),router=useRouter(),allowed=ref(false),busy=ref(false),error=ref(''),config=ref({}),stats=ref({}),syncState=ref({}),service=ref({}),overview=ref({}),validation=ref(null),mappings=ref([]),logs=ref([]),auditTotal=ref(0);
const tab=ref(route.query.tab||'status'),mappingKind=ref(route.query.kind||'principals'),keyword=ref(''),page=ref(Number(route.query.page)||1),size=ref(Number(route.query.size)||50),auditPerson=ref(''),auditAction=ref(''),since=ref(''),until=ref('');let sequence=0,poll;
const kinds=[['principals','Form 人员'],['units','Form 组织'],['identities','Form 任职'],['legacy/principals','历史人员'],['legacy/units','历史单位'],['legacy/identities','历史身份']];
const actions=[['UPLOAD','上传'],['DOWNLOAD','下载'],['DELETE','移入回收站'],['RESTORE','恢复'],['PURGE','永久删除'],['MOVE','移动'],['COPY','复制'],['RENAME','重命名'],['SHARE_CREATE','创建共享'],['SHARE_UPDATE','修改共享'],['SHARE_REVOKE','撤销共享'],['LINK_CREATE','创建外链'],['LINK_UPDATE','修改外链'],['LINK_REVOKE','停用外链'],['LINK_ACCESS','外链访问'],['EDIT_OPEN','打开编辑'],['EDIT_COMPLETED','编辑完成'],['EDIT_FAILED','编辑失败'],['MEMBER_ADD','成员加入'],['MEMBER_REMOVE','成员移除']];
const actionName=a=>actions.find(x=>x[0]===a)?.[1]||a;
const metrics=computed(()=>[{label:'Form 组织',value:stats.value.units||0},{label:'Form 人员',value:stats.value.persons||0},{label:'Form 任职',value:stats.value.identities||0},{label:'历史角色 / 群组',value:(stats.value.roles||0)+' / '+(stats.value.groups||0)}]);
const statusFields=computed(()=>({'服务阶段':service.value.phase,'同步阶段':syncState.value.phase||syncState.value.lastResult,'开始时间':syncState.value.lastStartedAt,'成功时间':syncState.value.lastSuccessAt||syncState.value.lastFinishedAt,'结果':syncState.value.lastOutcome||syncState.value.validationResult,'ETag':syncState.value.etag||syncState.value.lastEtag}));
const canonical=r=>r.canonicalPersonId||r.canonicalUnitId||r.canonicalIdentityId||'',legacy=r=>r.legacyOaPersonId||r.legacyOaUnitId||r.legacyOaIdentityId||'';
const stableId=r=>mappingKind.value.startsWith('legacy/')?r.oaId||legacy(r):r.formEmployeeId||r.formOrgId||r.formAssignmentId||r.externalId;
const filteredMappings=computed(()=>mappings.value.filter(r=>JSON.stringify(r).toLowerCase().includes(keyword.value.toLowerCase()))),mappingPage=computed(()=>filteredMappings.value.slice((page.value-1)*size.value,page.value*size.value));
function syncRoute(){router.replace({query:{tab:tab.value,kind:mappingKind.value,page:page.value,size:size.value}});}
async function switchTab(value){tab.value=value;page.value=1;syncRoute();await load();}
async function setPage(value){page.value=value;syncRoute();if(tab.value==='audit')await loadAudit();}
async function setSize(value){size.value=value;page.value=1;syncRoute();if(tab.value==='audit')await loadAudit();}
async function load(){
 const n=++sequence;busy.value=true;error.value='';
 try{const a=await api.getCurrentAdminStatus();if(n!==sequence)return;allowed.value=Boolean(a.admin);if(!a.admin)throw new Error('当前账号没有管理员权限');
 if(tab.value==='mapping'){await fetchMappings();[overview.value,validation.value]=await Promise.all([api.getFormMigrationOverview(),api.validateFormMigration()]);}
 else if(tab.value==='audit')await fetchAudit();
 else {[service.value,config.value,stats.value,syncState.value]=await Promise.all([api.getStatus(),api.getAdminConfig(),api.getSyncStats(),api.getFormDirectorySyncStatus()]);}
 }catch(e){if(n===sequence)error.value=e.message;}finally{if(n===sequence)busy.value=false;}
}
async function fetchMappings(){
 const rows=await api.listFormMigrationBindings(mappingKind.value);
 if(mappingKind.value.startsWith('legacy/')){const kind=mappingKind.value.slice(7),bindings=await api.listFormMigrationBindings(kind),field=kind==='principals'?'legacyOaPersonId':kind==='units'?'legacyOaUnitId':'legacyOaIdentityId';
 const byId=new Map(bindings.map(r=>[r[field],r]));mappings.value=rows.map(r=>({...r,...byId.get(r.oaId)}));}else mappings.value=rows;
}
async function loadMappings(){page.value=1;syncRoute();await load();}
async function validate(){validation.value=await api.validateFormMigration();await dialog({title:validation.value.ready?'切换校验通过':'切换校验存在阻断项',records:(validation.value.blockers||[]).map((r,i)=>({id:i,name:r.code||'阻断项',description:r.message||String(r)}))});}
async function editMapping(row){
 const options=({'legacy/units':['REUSE','MERGE','SPLIT','ARCHIVE','REVOKED'],'legacy/principals':['TOMBSTONE','ARCHIVE','TRANSFER'],'legacy/identities':['ARCHIVE','MERGE','REVOKED'],units:['REUSE','MERGE','SPLIT','ARCHIVE','NEW','REVOKED'],principals:['CONFIRMED','BIND','TRANSFER','TOMBSTONE','NEW','REVOKED']})[mappingKind.value]||['CONFIRMED','REUSE','ARCHIVE','NEW','REVOKED'];
 const result=await dialog({title:'处理映射 · '+(row.displayName||row.name||stableId(row)),description:'稳定 ID：'+stableId(row),fields:[{key:'decision',label:'处置',type:'select',options:options.map(o=>[o,o])},{key:'canonicalKey',label:'canonical key / 目标 key'},{key:'legacyOaId',label:'历史 OA key'},{key:'aliases',label:'后继 alias（用 | 分隔）'},{key:'note',label:'决策说明',type:'textarea',required:true}],values:{decision:options.includes(row.migrationDecision)?row.migrationDecision:options[0],canonicalKey:canonical(row),legacyOaId:legacy(row),aliases:'',note:row.note||''},
 onSubmit:v=>api.updateFormMigrationDecision(mappingKind.value,stableId(row),{...v,canonicalKey:v.canonicalKey||null,legacyOaId:v.legacyOaId||null,aliases:v.aliases.split('|').map(x=>x.trim()).filter(Boolean)})});
 if(result)await load();
}
async function importCsv(e){const f=e.target.files?.[0];e.target.value='';if(!f)return;await run(async()=>{if(!await confirm('导入组织映射？','将应用所选 CSV 的映射决策。'))return;await api.importFormUnitMappings(f);await load();notify('组织映射已导入，请复核校验结果');});}
async function fetchAudit(){const p=await api.getAuditLogs({person:auditPerson.value,action:auditAction.value,since:since.value?new Date(since.value+'T00:00:00').getTime():'',until:until.value?new Date(until.value+'T23:59:59').getTime():'',page:page.value,size:size.value});logs.value=p.content||[];auditTotal.value=p.totalElements||0;}
async function loadAudit(){await load();}
function showLog(row){void dialog({title:'审计详情',records:Object.entries(row).map(([k,v])=>({id:k,name:k,description:typeof v==='object'?JSON.stringify(v,null,2):String(v??'—')}))});}
async function syncNow(){await api.triggerFormDirectorySync();notify('已触发 Form 同步');await load();}
watch(keyword,()=>{page.value=1;});onMounted(()=>{void load();poll=setInterval(()=>{if(tab.value==='status'&&!busy.value)void load();},30000);});onUnmounted(()=>{sequence++;clearInterval(poll);});
</script>
